<script setup lang="ts">
import{onMounted,ref}from"vue";import{useRouter}from"vue-router";import{CircleCheck,Warning,SwitchButton}from"@element-plus/icons-vue";import{api}from"@/api";import{useUserStore}from"@/stores/user";import{err}from"@/utils/format";import PageHeader from"@/components/common/PageHeader.vue";import SectionPanel from"@/components/common/SectionPanel.vue";
const router=useRouter(),user=useUserStore(),health=ref<{status:string;ai_mode:string;modules:string[]}|null>(null),error=ref('');onMounted(async()=>{try{health.value=await api.health()}catch(e){error.value=err(e)}});function logout(){user.logout();router.replace('/login')}
</script><template><div><PageHeader title="系统设置" description="管理当前账号身份、显示偏好并查看系统服务状态。"/><div class="settings-grid"><SectionPanel :title="user.isRecruiter ? '当前招聘者' : '当前学生'"><div class="account-summary"><el-avatar :size="56">{{user.displayName.slice(0,1)}}</el-avatar><div><h3>{{user.displayName}}</h3><p>{{user.account?.email}}</p><span v-if="user.isRecruiter">招聘者 · 企业资料在招聘工作台维护</span><span v-else>档案编号：{{user.userId}} · {{user.user?.school}} · {{user.user?.major}} / {{user.user?.grade}}</span></div></div><el-button type="danger" plain :icon="SwitchButton" @click="logout">退出当前账号</el-button></SectionPanel><SectionPanel title="系统偏好"><div class="preference-row"><div><b>自动记住身份</b><span>登录状态通过有效凭证在刷新后恢复</span></div><el-tag type="success">已启用</el-tag></div><div class="preference-row"><div><b>界面语言</b><span>系统业务界面统一使用中文</span></div><el-tag>简体中文</el-tag></div></SectionPanel><SectionPanel title="服务状态"><div v-if="health" class="health-status"><el-icon class="ok"><CircleCheck/></el-icon><div><b>后端服务运行正常</b><span>AI模式：{{health.ai_mode==='live'?'真实模型':'演示模型'}}</span></div></div><div v-else class="health-status"><el-icon class="bad"><Warning/></el-icon><div><b>无法获取服务状态</b><span>{{error}}</span></div></div><ul class="module-list"><li v-for="x in health?.modules" :key="x">{{x}}</li></ul></SectionPanel><SectionPanel title="账号与安全"><el-alert :title="`当前绑定邮箱：${user.account?.email || '未获取'}。可在登录页通过邮箱验证码重置密码。`" type="info" :closable="false" show-icon/></SectionPanel></div></div></template>
